async function raw(path,body,token,method){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),20000);try{const r=await fetch(URL+path,{method:method||(body?'POST':'GET'),headers:{apikey:KEY,...(token?{Authorization:'Bearer '+token}:{}),...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined,signal:controller.signal});const data=await r.json().catch(()=>({}));if(!r.ok)throw new Error(data.msg||data.error_description||data.message||'No se pudo completar la operación.');return data}finally{clearTimeout(timer)}}
