async function authenticate(form,signup){const data=new FormData(form),email=data.get('email').trim(),password=data.get('password');status(signup?'Creando cuenta…':'Comprobando acceso…');if(signup){await raw('/auth/v1/signup',{email,password});status('Cuenta solicitada. Revisa tu correo para confirmarla y después pulsa Entrar.');form.elements.password.value='';return}const s=await raw('/auth/v1/token?grant_type=password',{email,password});session={...s,expires_at:Date.now()+s.expires_in*1000};epoch++;await command('claim_admin');await loadMembership();if(admin){await command('enable_self',{});workspace=desktop()?'home':'personal'}else workspace='personal';await refresh()}
async function loadMembership(){members=await rows('company_members','&user_id=eq.'+encodeURIComponent(session.user.id)+'&active=eq.true');const companies=await rows('companies','&status=eq.active');members=members.filter(m=>companies.some(c=>c.id===m.company_id));if(!members.length){company=null;admin=false;render();return}if(!company||!members.some(m=>m.company_id===company))company=members[0].company_id;admin=['owner','admin'].includes(members.find(m=>m.company_id===company)?.role)}
