function selectedServices(){return services.filter(s=>(!filters.date||local(s.starts_at).slice(0,10)===filters.date)&&(!filters.worker||s.employee_id===filters.worker)&&(filters.state==='all'||(filters.state==='active'?!['completed','cancelled'].includes(s.status):s.status===filters.state)))}
