async function reconcile(){const d=vault();if(!admin||!d)return;let changed=false;for(const remote of services){const s=d.servicios.find(s=>s.id===remote.id);if(!s||s.coord&&s.coord.company!==company)continue;const data={company,status:remote.status,version:remote.version};if(JSON.stringify(s.coord)!==JSON.stringify(data)){s.coord=data;changed=true}const employee=remote.employee_id||'';if(s.estado==='Pendiente'&&s.empleado!==employee){s.empleado=employee;changed=true}if(s.estado==='Pendiente'&&remote.status==='cancelled'){s.estado='Cancelado';changed=true}const date=local(remote.starts_at).slice(0,10),time=local(remote.starts_at).slice(11,16),hours=(new Date(remote.ends_at)-new Date(remote.starts_at))/3600000;if(s.estado==='Pendiente'&&(s.fecha!==date||s.hora!==time||Number(s.horas)!==hours)){if(Number(s.horas)!==hours&&s.modo==='puntual'){s.precio=Math.round((s.tarifaHora??(Number(s.precio)/Number(s.horas))) *hours*100)/100}s.fecha=date;s.hora=time;s.horas=hours;changed=true}}if(changed&&!await persist())throw new Error('Los cambios están guardados en coordinación, pero falta guardar su copia en Gestión. Vuelve a actualizar sin cerrar la app.')}
