function card(s,personal=false){const w=workers.find(w=>w.employee_id===s.employee_id);let controls='';if(admin&&!personal){if(['unassigned','offered','assigned'].includes(s.status))controls+=assignment(s);if(s.status==='unassigned')controls+=reschedule(s);if(s.status==='incident')controls+=button('resolve','Resolver incidencia',s);if(!['completed','cancelled'].includes(s.status))controls+=button('cancel','Cancelar servicio',s,'danger');if(s.status==='completed')controls+='<p class="coord-muted">Pendiente de revisar y cerrar en Gestión para conservar el cálculo de cobros.</p>'}else{if(s.status==='offered')controls+=button('accept','Aceptar',s,'primary')+button('reject','Rechazar',s,'danger');if(s.status==='assigned')controls+=button('start','Iniciar servicio',s,'primary');if(s.status==='in_progress')controls+=button('complete','Finalizar servicio',s,'primary');if(['assigned','in_progress'].includes(s.status))controls+=button('incident','Comunicar incidencia',s)}const phone=s.phone.replace(/[^+\d]/g,'');return '<article class="coord-card"><div class="coord-date">'+e(pretty(s.starts_at))+' — '+e(pretty(s.ends_at))+'</div><div class="coord-itemhead"><h3>'+e(s.title)+'</h3><span class="coord-pill '+e(s.status)+'">'+e(labels[s.status])+'</span></div><p><b>'+e(s.client_name)+'</b></p><p>'+e(s.address||'Sin dirección indicada')+'</p><p>'+e(s.instructions||'Sin instrucciones adicionales')+'</p>'+(admin&&!personal?'<p class="coord-muted">'+e(w?.name||'Sin trabajador')+' · '+e(s.id)+'</p>':'')+'<div class="coord-actions">'+(phone?'<a class="coord-btn" href="tel:'+e(phone)+'">Llamar</a>':'')+(s.address?'<a class="coord-btn" target="_blank" rel="noopener noreferrer" href="https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(s.address)+'">Ubicación</a>':'')+'</div><div class="coord-actions" style="margin-top:14px">'+controls+'</div></article>'}
