function publishPanel(){const d=vault();if(!d)return '<section class="coord-card"><h2>Enviar servicios desde Gestión</h2><p>Abre Gestión con tu contraseña y vuelve a coordinación para publicar los servicios existentes.</p></section>';const candidates=d.servicios.filter(s=>s.estado==='Pendiente');return '<section class="coord-card"><h2>Enviar desde Gestión</h2><p class="coord-muted">Se comparte nombre, teléfono, dirección, horario y las instrucciones que indiques aquí. No se comparten tarifas, cobros ni notas privadas del cliente.</p><form id="coordPublish"><label class="coord-field">Servicio<select name="id" required><option value="">Selecciona un servicio</option>'+candidates.map(s=>'<option value="'+e(s.id)+'">'+e(s.fecha+' '+s.hora+' · '+(d.clientes.find(c=>c.id===s.cliente)?.nombre||'Cliente')+(services.some(c=>c.id===s.id)?' · Publicado':''))+'</option>').join('')+'</select></label><label class="coord-field">Instrucciones para el trabajador<textarea name="instructions" maxlength="4000" placeholder="Solo la información necesaria para prestar el servicio"></textarea></label><p id="coordPreview" class="coord-muted"></p><button class="coord-btn primary" type="submit">Publicar / actualizar datos</button></form><p class="coord-muted">Las asignaciones y bloqueos de coordinación se gestionan aquí. Los bloqueos antiguos de Gestión se pueden incorporar con el botón siguiente.</p><button class="coord-btn" data-action="import-blocks">Incorporar bloqueos de Gestión</button></section>'}
