function calendar(){const year=calendarMonth.getFullYear(),month=calendarMonth.getMonth(),start=new Date(year,month,1);let days;
 if(calendarView==='week'){const chosen=new Date((filters.date||day())+'T12:00:00');start.setTime(chosen.getTime());start.setDate(start.getDate()-(start.getDay()+6)%7);days=7}
 else{start.setDate(1-(start.getDay()+6)%7);days=42}
 const available=filteredCalendarServices();let cells='';for(let n=0;n<days;n++){const d=new Date(start);d.setDate(d.getDate()+n);const key=dateKey(d),items=available.filter(s=>onDate(s,key)),selected=key===filters.date,today=key===day();cells+='<button type="button" class="coord-calday '+(selected?'selected ':'')+(today?'is-today ':'')+(d.getMonth()!==month&&calendarView==='month'?'outside ':'')+'" data-action="pick-date" data-date="'+key+'" aria-label="'+e(d.toLocaleDateString('es-ES',{weekday:'long',day:'numeric',month:'long'}))+', '+items.length+' servicios" aria-pressed="'+selected+'"><span class="coord-daynum">'+d.getDate()+'</span>'+(items.length?'<span class="coord-daycount">'+items.length+'</span>':'')+'<span class="coord-calitems">'+items.slice(0,calendarView==='week'?8:2).map(s=>'<span class="coord-calevent '+e(s.status)+'"><i></i><span>'+e(local(s.starts_at).slice(11,16)+' '+(s.client_name||s.title))+'</span></span>').join('')+(items.length>(calendarView==='week'?8:2)?'<small>+'+(items.length-(calendarView==='week'?8:2))+' más</small>':'')+'</span></button>'}
 const heading=calendarView==='week'?'Semana del '+start.toLocaleDateString('es-ES',{day:'numeric',month:'long'}):calendarMonth.toLocaleDateString('es-ES',{month:'long',year:'numeric'});
 return '<section class="coord-calendar"><div class="coord-calhead"><div><span class="coord-eyebrow">PLANIFICACIÓN</span><h2>'+e(heading)+'</h2></div><div class="coord-actions"><button class="coord-iconbtn" data-action="previous" aria-label="Periodo anterior">‹</button><button class="coord-btn" data-action="today">Hoy</button><button class="coord-iconbtn" data-action="next" aria-label="Periodo siguiente">›</button></div></div><div class="coord-calweek">'+['Lun','Mar','Mié','Jue','Vie','Sáb','Dom'].map(d=>'<span>'+d+'</span>').join('')+'</div><div class="coord-caldays '+(calendarView==='week'?'week':'')+'">'+cells+'</div><div class="coord-legend">'+[['unassigned','Por asignar'],['offered','Propuesto'],['assigned','Asignado'],['in_progress','En curso'],['incident','Incidencia']].map(([id,text])=>'<span><i class="'+id+'"></i>'+text+'</span>').join('')+'</div></section>';
}
function dailyAgenda(){const date=filters.date||day(),items=filteredCalendarServices().filter(s=>onDate(s,date));return '<section class="coord-daily"><div class="coord-dailyhead"><span class="coord-eyebrow">AGENDA DEL DÍA</span><h2>'+e(new Date(date+'T12:00:00').toLocaleDateString('es-ES',{weekday:'long',day:'numeric',month:'long'}))+'</h2><span class="coord-muted">'+items.length+' servicio(s) · selecciona uno para coordinar</span></div><div class="coord-dailylist">'+(items.length?items.map(s=>'<details class="coord-appointment"><summary><span class="coord-appointmenttime">'+e(local(s.starts_at).slice(11,16))+'<small>'+e(local(s.ends_at).slice(11,16))+'</small></span><span class="coord-appointmentcopy"><b>'+e(s.client_name||s.title)+'</b><span>'+e(s.title)+'</span><span class="coord-pill '+e(s.status)+'">'+e(labels[s.status])+'</span></span><span aria-hidden="true">⌄</span></summary>'+card(s)+'</details>').join(''):'<div class="coord-dayempty"><span aria-hidden="true">▦</span><h3>Tu agenda está despejada</h3><p>No hay servicios con estos filtros.</p><button class="coord-btn primary" data-action="new-service">＋ Crear servicio</button></div>')+'</div><button class="coord-dailyadd" data-action="new-service">＋ Añadir servicio para este día</button></section>'}
function notices(){return '<section class="coord-card"><div class="coord-sectionhead"><div><span class="coord-eyebrow">SEGUIMIENTO</span><h2>Avisos e historial</h2></div><span class="coord-muted">Últimos 80 movimientos</span></div>'+(events.length?events.map(ev=>'<div class="coord-event"><span class="coord-eventdot"></span><div><b>'+e(actions[ev.action]||ev.action)+'</b><p>'+e(ev.service_id||'Equipo')+' · '+e(ev.detail)+'</p></div><time>'+e(pretty(ev.created_at))+'</time></div>').join(''):'<div class="coord-empty">Aquí aparecerán las aceptaciones, rechazos e incidencias del equipo.</div>')+'</section>'}
function teamView(){return '<div class="coord-teamlayout">'+workerPanel()+availability()+'</div>'}
function dashboard(){const counts=[['unassigned','Por asignar','Pendientes de coordinar'],['offered','Esperando respuesta','Propuestas al equipo'],['in_progress','En curso','Servicios iniciados'],['incident','Incidencias','Requieren tu atención']];
 const nav=[['agenda','▦','Calendario'],['equipo','♙','Equipo y disponibilidad'],['avisos','◉','Avisos e historial'],['gestion','⇄','Servicios de Gestión']];
 return '<div class="coord-workspace"><nav class="coord-rail" aria-label="Secciones de coordinación"><div class="coord-railbrand"><img src="umec-logo.svg" alt="UMEC"><b>COORDINACIÓN<small>Centro de operaciones</small></b></div><p class="coord-railcaption">ESPACIO DE TRABAJO</p>'+nav.map(([id,icon,title])=>'<button data-action="section" data-section="'+id+'" class="'+(section===id?'active':'')+'"><span aria-hidden="true">'+icon+'</span>'+title+'</button>').join('')+'<div class="coord-railfoot"><span class="coord-online"></span> Coordinación del equipo<small>Los cambios se comparten con cada trabajador.</small></div></nav><div class="coord-main"><div class="coord-hero"><div><span class="coord-eyebrow">UMEC / OPERACIONES</span><h1>'+({agenda:'Cada servicio, en su sitio.',equipo:'Tu equipo, organizado.',avisos:'Todo lo que necesitas saber.',gestion:'Conecta tu gestión diaria.'}[section])+'</h1><p>'+({agenda:'Planifica, asigna y sigue los servicios desde un mismo calendario.',equipo:'Consulta las reservas de cada persona y organiza su disponibilidad.',avisos:'Sigue las respuestas del equipo y resuelve las incidencias.',gestion:'Incorpora los servicios que ya tienes guardados en Gestión.'}[section])+'</p></div><button class="coord-btn primary coord-createbutton" data-action="new-service">＋ Crear servicio</button></div><div id="coordStatus" class="coord-status" role="status" aria-live="polite"><span class="coord-online"></span> '+(lastAt?'Actualizado a las '+e(lastAt):'Conectando con el equipo…')+'<small>Sincronización cada 15 s</small></div><div class="coord-metrics">'+counts.map(([id,name,detail])=>'<button class="coord-metric '+id+'" data-action="metric" data-state="'+id+'"><span>'+name+'</span><strong>'+services.filter(s=>s.status===id).length+'</strong><small>'+detail+'</small></button>').join('')+'</div>'+(section==='agenda'?'<div class="coord-toolbar"><div class="coord-segment" aria-label="Vista del calendario"><button data-action="view" data-view="month" aria-pressed="'+(calendarView==='month')+'" class="'+(calendarView==='month'?'active':'')+'">Mes</button><button data-action="view" data-view="week" aria-pressed="'+(calendarView==='week')+'" class="'+(calendarView==='week'?'active':'')+'">Semana</button></div><div class="coord-toolbarfilters"><label>Estado<select id="coordState">'+options([['active','Servicios activos'],['all','Todos los estados'],...Object.entries(labels)],filters.state)+'</select></label><label>Trabajador<select id="coordWorkerFilter">'+options([['','Todo el equipo'],...workers.map(w=>[w.employee_id,w.name])],filters.worker)+'</select></label></div></div><div class="coord-planning">'+calendar()+dailyAgenda()+'</div>':section==='equipo'?teamView():section==='avisos'?notices():publishPanel())+'</div></div>';
}
function createDialog(){const d=createDraft;const date=d.date||filters.date||day();const clients=vault()?.clientes||[];return '<div class="coord-dialogback"><section class="coord-dialog" role="dialog" aria-modal="true" aria-labelledby="coordCreateTitle"><div class="coord-dialoghead"><div><span class="coord-eyebrow">NUEVO SERVICIO</span><h2 id="coordCreateTitle">Organiza el próximo servicio</h2></div><button type="button" class="coord-iconbtn" data-action="close-create" aria-label="Cerrar formulario">×</button></div><form id="coordCreate"><div class="coord-dialogbody"><p class="coord-muted">El servicio se guarda en coordinación y se comparte con el trabajador que elijas.</p><div id="coordCreateError" class="coord-status error" role="alert"'+(!createError?' hidden':'')+'>'+e(createError)+'</div>'+(clients.length?'<label class="coord-field">Seleccionar un cliente de Gestión (opcional)<select name="client_ref"><option value="">Introducir datos del cliente</option>'+options(clients.map(c=>[c.id,c.nombre]),d.client_ref||'')+'</select></label>':'')+'<div class="coord-formsection"><h3>01 <span>Cliente y servicio</span></h3><div class="coord-two"><label class="coord-field">Nombre del cliente *<input name="client_name" maxlength="200" required value="'+e(d.client_name)+'" autocomplete="name"></label><label class="coord-field">Teléfono de contacto<input name="phone" maxlength="80" type="tel" value="'+e(d.phone)+'" autocomplete="tel"></label></div><label class="coord-field">Tipo de servicio *<input name="title" maxlength="200" required value="'+e(d.title)+'" placeholder="Acompañamiento, atención en domicilio, recados…" list="coordTypes"></label><datalist id="coordTypes"><option value="Acompañamiento"><option value="Atención en domicilio"><option value="Acompañamiento médico"><option value="Recados y gestiones"></datalist><label class="coord-field">Dirección<input name="address" maxlength="1000" value="'+e(d.address)+'" autocomplete="street-address" placeholder="Calle, número, localidad y detalles de acceso"></label></div><div class="coord-formsection"><h3>02 <span>Fecha y horario</span></h3><div class="coord-three"><label class="coord-field">Día *<input name="date" type="date" required value="'+e(date)+'"></label><label class="coord-field">Inicio *<input name="time" type="time" required value="'+e(d.time||'09:00')+'"></label><label class="coord-field">Duración (horas) *<input name="hours" type="number" min="0.5" max="24" step="0.5" required value="'+e(d.hours||'1')+'"></label></div></div><div class="coord-formsection"><h3>03 <span>Asignación e instrucciones</span></h3><div class="coord-two"><label class="coord-field">Trabajador<select name="employee_id">'+workerChoices(d.employee_id||'','Asignar más adelante')+'</select></label><label class="coord-field">Modalidad<select name="mode">'+options([['direct','Asignación directa'],['acceptance','Solicitar aceptación']],d.mode||'direct')+'</select></label></div><label class="coord-field">Instrucciones para el trabajador<textarea name="instructions" maxlength="4000" placeholder="Solo la información necesaria para prestar el servicio">'+e(d.instructions)+'</textarea></label>'+workerHelp()+'<p class="coord-muted">Se comprobarán los solapamientos antes de asignar. El cierre y los cobros se revisan en Gestión.</p></div></div><div class="coord-dialogfoot"><button type="button" class="coord-btn" data-action="close-create">Cancelar</button><button type="submit" class="coord-btn primary">Crear y guardar servicio</button></div></form></section></div>'}
function renderDashboardOld(){if(!session||!company||!admin||!desktop()){renderLegacy();return}root.innerHTML=header()+dashboard()+(createOpen?createDialog():'');root.querySelectorAll('button').forEach(b=>b.disabled=busy)}
async function createService(form){if(!admin||!desktop())throw new Error('Solo administradores en ordenador.');const data=Object.fromEntries(new FormData(form));const hours=Number(data.hours),start=new Date(data.date+'T'+data.time),end=new Date(start.getTime()+hours*3600000);if(!data.client_name?.trim()||!data.title?.trim())throw new Error('Indica el cliente y el tipo de servicio.');if(!Number.isFinite(start.getTime())||!(hours>=.5&&hours<=24&&Number.isInteger(hours*2)))throw new Error('Revisa la fecha y la duración (de 0,5 a 24 horas).');const payload={request_id:createDraft.request_id||(createDraft.request_id=crypto.randomUUID()),client_name:data.client_name.trim(),title:data.title.trim(),phone:(data.phone||'').trim(),address:(data.address||'').trim(),instructions:data.instructions||'',starts_at:start.toISOString(),ends_at:end.toISOString(),employee_id:data.employee_id||'',mode:data.mode||'direct'};const conflict=legacyConflict(payload.employee_id,payload);if(conflict)throw new Error(conflict);if(payload.employee_id&&vault())await importBlocks();const result=await command('create',payload);if(!result.id)throw new Error('No se recibió la confirmación del servicio. Actualiza la agenda antes de repetir.');return {result,date:local(result.starts_at).slice(0,10),clientRef:data.client_ref}}
async function importNativeServices(){
 const d=vault();if(!admin||!d)return;
 const pending=services.filter(s=>s.id.startsWith('COORD-')&&!d.servicios.some(x=>x.id===s.id));if(!pending.length)return;
 const rates=typeof currentRates==='function'?currentRates():null;
 if(!rates||!Number.isFinite(Number(rates.hour)))throw new Error('No se pudieron consultar las tarifas de Gestión.');
 const previousClients=d.clientes,previousServices=d.servicios;d.clientes=[...d.clientes];d.servicios=[...d.servicios];
 try{for(const s of pending){let c=d.clientes.find(c=>c.nombre===s.client_name&&(c.telefono||'')===s.phone);if(!c){c={id:'CL-'+s.id,nombre:s.client_name,telefono:s.phone,direccion:s.address,notas:''};d.clientes.push(c)}
 const hours=(new Date(s.ends_at)-new Date(s.starts_at))/3600000;
 d.servicios.push({id:s.id,cliente:c.id,empleado:s.employee_id||'',fecha:local(s.starts_at).slice(0,10),hora:local(s.starts_at).slice(11,16),tipo:s.title,modo:'puntual',bono:null,horas:hours,direccion:s.address,notas:s.instructions,estado:s.status==='cancelled'?'Cancelado':'Pendiente',excesoMin:0,extra:0,precio:Math.round(rates.hour*hours*100)/100,tarifaHora:rates.hour,tarifaExtra:rates.hourExtra,tarifaCortesia:rates.grace,coord:{company,status:s.status,version:s.version}})}
 if(!await persist())throw new Error('Servicio guardado en coordinación. No cierres Gestión: falta guardar su copia local.');
 }catch(err){d.clientes=previousClients;d.servicios=previousServices;if(typeof renderAll==='function')renderAll();throw err}
}
// One personal sign-in. Authoritative permissions remain independent of the selected view.
let workspace='home',personalFilters={date:'',state:'active'};
function ownWorkers(){return workers.filter(w=>w.user_id===session?.user.id&&w.active)}
function myServices(){const ids=new Set(ownWorkers().map(w=>w.employee_id));return services.filter(s=>ids.has(s.employee_id))}
function header(){const title=!session?'Acceso personal':admin?({home:'Mi espacio',personal:'Mis servicios',coordination:'Centro de Coordinación',management:'Gestión'}[workspace]||'Mi espacio'):'Mis servicios';return '<header class="coord-bar"><div><b>UMEC · '+title+'</b><small>'+(session?e(session.user.email)+' · '+(admin?'Administrador y profesional':'Trabajador'):'Cada persona entra con su propia cuenta')+'</small></div><div class="coord-actions">'+(session?(admin?'<button class="coord-btn" data-action="workspace" data-workspace="home">Mi espacio</button><button class="coord-btn" data-action="workspace" data-workspace="personal">Mis servicios</button>':'')+'<button class="coord-btn" data-action="refresh">Actualizar</button><button class="coord-btn" data-action="logout">Cerrar sesión</button>':'')+'</div></header>'}
function login(){root.innerHTML=header()+'<div class="coord-access"><section class="coord-welcome"><img src="umec-logo.svg" alt="UMEC"><span class="coord-eyebrow">UNA MANO EN CASA</span><h1>Tu trabajo. <br>Todo en un mismo lugar.</h1><p>Servicios, equipo y coordinación, conectados.</p><div class="coord-accessbenefit"><b>Para el equipo</b><span>Consulta tus servicios y comunica su progreso.</span></div><div class="coord-accessbenefit"><b>Para ti, como administrador</b><span>Coordina al equipo y realiza tus propios servicios con la misma cuenta.</span></div></section><section class="coord-signin"><span class="coord-eyebrow">ACCESO A UMEC</span><h2>Bienvenido de nuevo</h2><p>Entra con tu correo y tu contraseña personal.</p><div id="coordStatus" class="coord-status" role="status" aria-live="polite">Tus permisos se reconocen automáticamente al entrar.</div><form id="coordLogin"><label class="coord-field">Correo electrónico<input name="email" type="email" autocomplete="username" required placeholder="nombre@correo.com"></label><label class="coord-field">Contraseña de tu cuenta<input name="password" type="password" autocomplete="current-password" minlength="8" required placeholder="Tu contraseña personal"></label><button class="coord-btn primary coord-signinbutton" type="submit">Entrar a mi espacio</button><div class="coord-register"><span>¿Es tu primera vez?</span><button class="coord-btn" type="submit" name="signup" value="yes">Crear mi cuenta</button></div></form><p class="coord-accessnote">Si eres trabajador, tu administrador debe vincular tu cuenta después de confirmar el correo.</p><details class="coord-accessfaq"><summary>¿Qué contraseña debo utilizar?</summary><p>Usa la contraseña que elegiste al crear tu cuenta con correo. La contraseña antigua de Gestión solo se solicita al administrador cuando abre sus datos guardados.</p></details></section></div>'}
async function syncOwnProfile(){const d=vault(),own=ownWorkers()[0];if(!admin||!d||!own||(d.empleados||[]).some(w=>w.id===own.employee_id))return;const previous=d.empleados;d.empleados=[...(previous||[]),{id:own.employee_id,nombre:own.name,email:session.user.email,whatsapp:'',puesto:'Administrador · servicios',direccion:'',notas:''}];try{if(!await persist())throw new Error('Falta guardar tu perfil de servicios en Gestión. Actualiza sin cerrar la app.')}catch(err){d.empleados=previous;throw err}}
function renderHome(){const own=ownWorkers()[0],count=myServices().filter(s=>!['completed','cancelled'].includes(s.status)).length;root.innerHTML=header()+'<div class="coord-home"><span class="coord-eyebrow">TU CUENTA UMEC</span><h1>Elige dónde quieres trabajar</h1><p>Tu cuenta de administrador también sirve para realizar servicios. Cambia de espacio sin cerrar sesión.</p><div id="coordStatus" class="coord-status" role="status" aria-live="polite">'+(own?'Tu perfil de servicios está activo. Ya puedes asignarte servicios desde Coordinación.':'Comprobando tu perfil de servicios…')+'</div><div class="coord-homecards"><button class="coord-homecard" data-action="workspace" data-workspace="personal"><span class="coord-homeicon">◷</span><h2>Mis servicios</h2><p>Tu agenda personal, propuestas y servicios que vas a realizar.</p><small>'+count+' servicio(s) activo(s)</small><strong>Ver mi agenda →</strong></button><button class="coord-homecard" data-action="workspace" data-workspace="coordination"><span class="coord-homeicon">▦</span><h2>Coordinación</h2><p>Crea servicios, organiza horarios y asigna al equipo o a ti mismo.</p><small>'+(desktop()?'Disponible en este ordenador':'Disponible desde el ordenador')+'</small><strong>'+(desktop()?'Abrir coordinación →':'Abrir en ordenador')+'</strong></button><button class="coord-homecard" data-action="workspace" data-workspace="management"><span class="coord-homeicon">▤</span><h2>Gestión</h2><p>Clientes, tarifas, packs, cobros y copias de seguridad.</p><small>'+(vault()?'Tus datos ya están desbloqueados':'Requiere desbloquear tus datos guardados')+'</small><strong>Abrir Gestión →</strong></button></div><p class="coord-muted">Una cuenta personal para entrar. La clave de protección de Gestión conserva tus datos anteriores.</p></div>'}
function renderPersonal(){const own=ownWorkers(),items=myServices().filter(s=>(!personalFilters.date||onDate(s,personalFilters.date))&&(personalFilters.state==='all'||(personalFilters.state==='active'?!['completed','cancelled'].includes(s.status):s.status===personalFilters.state)));root.innerHTML=header()+'<main class="coord-personal"><span class="coord-eyebrow">MI AGENDA</span><h1>Mis servicios</h1><p class="coord-muted">'+(admin?'Aquí ves solo los servicios que tú realizas. Tu acceso de administrador se mantiene.':'Aquí recibes tus servicios, aceptas propuestas y comunicas el progreso.')+'</p><div id="coordStatus" class="coord-status" role="status" aria-live="polite">'+(lastAt?'Actualizado a las '+e(lastAt):'Conectando…')+'</div>'+(!own.length?'<div class="coord-empty"><h2>Tu cuenta aún no está vinculada</h2><p>Ya has iniciado sesión. Pide al administrador que vincule este correo a tu ficha de trabajador.</p><p><b>'+e(session.user.email)+'</b></p><button class="coord-btn primary" data-action="refresh">Comprobar mi acceso</button></div>':'<div class="coord-filter"><label>Día<input id="coordPersonalDate" type="date" value="'+e(personalFilters.date)+'"></label><label>Estado<select id="coordPersonalState">'+options([['active','Servicios activos'],['all','Todos los estados'],...Object.entries(labels)],personalFilters.state)+'</select></label><button class="coord-btn" data-action="personal-all-dates">Ver todas mis fechas</button></div><div class="coord-personalservices">'+(items.map(s=>card(s,true)).join('')||'<div class="coord-empty"><h2>Sin servicios para este filtro</h2><p>Las nuevas asignaciones aparecerán aquí automáticamente.</p></div>')+'</div>'+availability(true))+'</main>';root.querySelectorAll('button').forEach(b=>b.disabled=busy)}
function render(){if(!session){login();return}if(!company){renderPersonal();return}if(!admin){workspace='personal';renderPersonal();return}if(workspace==='personal'){renderPersonal();return}if(workspace==='coordination'&&desktop()){root.innerHTML=header()+dashboard()+(createOpen?createDialog():'');root.querySelectorAll('button').forEach(b=>b.disabled=busy);return}if(workspace==='coordination'&&!desktop())workspace='home';renderHome()}
async function openManagement(){if(!session||!admin){status('Gestión está reservada a la cuenta del administrador.',true);return}await token();await loadMembership();if(!admin){render();return}workspace='management';createOpen=false;if(vault()){root.hidden=true;return}showAuth(authMode||'login');root.hidden=true;document.getElementById('authPassword')?.focus()}
root.addEventListener('click',async event=>{const b=event.target.closest('[data-action]');if(!b||!['workspace','personal-all-dates'].includes(b.dataset.action))return;event.preventDefault();event.stopImmediatePropagation();if(busy||!session)return;if(b.dataset.action==='personal-all-dates'){personalFilters.date='';render();return}if(!admin)return;const target=b.dataset.workspace;if(target==='management'){try{await openManagement()}catch(err){status(err.message,true)}return}createOpen=false;dirtyForm=false;workspace=target;render();root.scrollTop=0});
root.addEventListener('change',event=>{if(event.target.id==='coordPersonalDate'){personalFilters.date=event.target.value;render()}if(event.target.id==='coordPersonalState'){personalFilters.state=event.target.value;render()}});
const legacyShowAuth=showAuth;
showAuth=function(mode){legacyShowAuth(mode);if(q('authTitle'))q('authTitle').textContent=mode==='setup'?'Proteger datos de Gestión':'Desbloquear datos de Gestión';if(q('authIntro'))q('authIntro').textContent='Solo administrador. Esta clave protege tus clientes, cobros y copias guardadas.';if(q('authSubmit'))q('authSubmit').textContent=mode==='setup'?'Proteger mis datos':'Desbloquear Gestión';if(q('authPassword'))q('authPassword').placeholder='Contraseña de protección de Gestión';if(q('forgotPasswordBtn'))q('forgotPasswordBtn').textContent='Recuperar mis datos de Gestión'};
const legacySubmitAuth=submitAuth;
submitAuth=async function(){if(!session||!admin){root.hidden=false;render();return}try{await token();await loadMembership();if(!admin){root.hidden=false;render();return}await legacySubmitAuth();if(vault()){workspace='management';root.hidden=true}}catch(err){if(q('authError'))q('authError').textContent=err.message}};

root.addEventListener('click',event=>{const b=event.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;if(!['section','view','previous','next','today','pick-date','metric','new-service','close-create','setup-team'].includes(action))return;event.stopImmediatePropagation();event.preventDefault();if(busy)return;if(!admin||!desktop())return;
 if(action==='section'){section=b.dataset.section;dirtyForm=false}if(action==='setup-team'){createOpen=false;section='equipo';dirtyForm=false}
 if(action==='view')calendarView=b.dataset.view;
 if(action==='previous'||action==='next'){const n=action==='next'?1:-1;if(calendarView==='week'){const date=new Date((filters.date||day())+'T12:00:00');date.setDate(date.getDate()+7*n);filters.date=dateKey(date);calendarMonth=new Date(date.getFullYear(),date.getMonth(),1)}else{calendarMonth=new Date(calendarMonth.getFullYear(),calendarMonth.getMonth()+n,1);filters.date=dateKey(calendarMonth)}}
 if(action==='today'){filters.date=day();const date=new Date();calendarMonth=new Date(date.getFullYear(),date.getMonth(),1)}
 if(action==='pick-date')filters.date=b.dataset.date;
 if(action==='metric'){section='agenda';filters.state=b.dataset.state;const next=services.find(s=>s.status===filters.state&&(!filters.worker||s.employee_id===filters.worker));if(next){filters.date=local(next.starts_at).slice(0,10);const date=new Date(filters.date+'T12:00:00');calendarMonth=new Date(date.getFullYear(),date.getMonth(),1)}}
 if(action==='new-service'){epoch++;createDraft.request_id||=crypto.randomUUID();createOpen=true;createError='';dirtyForm=true}
 if(action==='close-create'){createOpen=false;dirtyForm=false}
 render();if(createOpen)root.querySelector('#coordCreate input')?.focus();else if(action==='close-create')root.querySelector('[data-action="new-service"]')?.focus();
});
root.addEventListener('input',event=>{if(event.target.form?.id==='coordCreate')createDraft[event.target.name]=event.target.value});
root.addEventListener('change',event=>{const t=event.target;if(t.form?.id!=='coordCreate')return;createDraft[t.name]=t.value;if(t.name==='client_ref'){const c=vault()?.clientes.find(c=>c.id===t.value);if(c){for(const [name,value] of Object.entries({client_name:c.nombre,phone:c.telefono||'',address:typeof addressOf==='function'?addressOf(c):c.direccion||''})){createDraft[name]=value;t.form.elements[name].value=value}}}});
root.addEventListener('submit',async event=>{if(event.target.id!=='coordCreate')return;event.preventDefault();event.stopImmediatePropagation();if(busy)return;busy=true;root.querySelectorAll('button').forEach(b=>b.disabled=true);let saved=false;try{const created=await createService(event.target);saved=true;createOpen=false;createDraft={};createError='';dirtyForm=false;filters.date=created.date;filters.state='active';filters.worker='';calendarMonth=new Date(new Date(created.date+'T12:00:00').getFullYear(),new Date(created.date+'T12:00:00').getMonth(),1);section='agenda';render();const synced=await refresh();if(!synced){status('El servicio se ha creado. Pulsa Actualizar para comprobar la agenda y su copia en Gestión.',true);return}status('Servicio creado'+(created.result.status==='offered'?' y enviado para aceptación.':created.result.status==='assigned'?' y asignado al trabajador.':'. Ya puedes asignarlo desde su ficha.'))}catch(err){if(!saved){createError=err.message;const el=q('coordCreateError');if(el){el.textContent=createError;el.hidden=false}dirtyForm=true}else status('Servicio creado en coordinación. '+err.message,true)}finally{busy=false;root.querySelectorAll('button').forEach(b=>b.disabled=false)}});
root.addEventListener('keydown',event=>{if(!createOpen)return;if(event.key==='Escape'){event.preventDefault();createOpen=false;dirtyForm=false;render();root.querySelector('[data-action="new-service"]')?.focus()}if(event.key==='Tab'){const dialog=root.querySelector('.coord-dialog'),all=[...dialog.querySelectorAll('button,input,select,textarea')].filter(el=>!el.disabled),first=all[0],last=all[all.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}});

root.addEventListener('submit',async event=>{event.preventDefault();if(busy)return;dirtyForm=false;busy=true;root.querySelectorAll('button').forEach(b=>b.disabled=true);const form=event.target;try{if(form.id==='coordLogin'){await authenticate(form,event.submitter?.name==='signup');return}if(!session)throw new Error('Inicia sesión.');if(form.id==='coordWorker'){const d=new FormData(form),worker=vault()?.empleados?.find(w=>w.id===d.get('employee_id'));if(!worker)throw new Error('Selecciona un empleado de Gestión.');await command('worker',{employee_id:worker.id,name:worker.nombre,email:d.get('email').trim(),active:d.get('active')==='true'})}if(form.id==='coordPublish')await publish(form);if(form.classList.contains('coordSchedule')){const s=services.find(s=>s.id===form.dataset.id),data=Object.fromEntries(new FormData(form));const start=new Date(data.starts_at),end=new Date(data.ends_at),hours=(end-start)/3600000,legacy=vault()?.servicios.find(x=>x.id===s.id);if(!(hours>=.5&&hours<=24&&Number.isInteger(hours*2)))throw new Error('La duración debe ser de 0,5 a 24 horas, en pasos de media hora.');if(legacy?.modo==='bono'&&typeof editablePackHours==='function'&&hours>editablePackHours(legacy))throw new Error('La duración supera el saldo disponible del pack.');if(legacy?.modo==='puntual'&&hours!==Number(legacy.horas)&&!confirm('La duración cambia el importe del servicio en Gestión. ¿Guardar?'))return;await command('publish',{...s,starts_at:start.toISOString(),ends_at:end.toISOString(),instructions:data.instructions})}if(form.id==='coordAvailability'){const data=Object.fromEntries(new FormData(form));data.starts_at=new Date(data.starts_at).toISOString();data.ends_at=new Date(data.ends_at).toISOString();await command('availability',data)}await refresh();status('Cambios guardados y disponibles para el equipo.')}catch(err){status(err.message,true)}finally{busy=false;root.querySelectorAll('button').forEach(b=>b.disabled=false)}});
root.addEventListener('change',async event=>{const t=event.target;if(t.id==='coordCompany'){createDraft={};createOpen=false;dirtyForm=false;company=t.value;epoch++;await refresh();return}if(t.id==='coordDate')filters.date=t.value;if(t.id==='coordState')filters.state=t.value;if(t.id==='coordWorkerFilter')filters.worker=t.value;if(['coordDate','coordState','coordWorkerFilter'].includes(t.id))render();if(t.form?.id==='coordPublish'&&t.name==='id'){const s=vault()?.servicios.find(s=>s.id===t.value),c=vault()?.clientes.find(c=>c.id===s?.cliente),old=services.find(s=>s.id===t.value);t.form.elements.instructions.value=old?.instructions||'';q('coordPreview').textContent=s&&c?c.nombre+' · '+(c.telefono||'Sin teléfono')+' · '+(s.direccion||addressOf(c))+' · '+s.fecha+' '+s.hora+' · '+s.horas+' h':''}});
root.addEventListener('click',async event=>{const b=event.target.closest('[data-action]');if(!b||busy)return;const action=b.dataset.action;if(action==='close'){if(admin)openManagement();return}if(action==='all-dates'){filters.date='';render();return}busy=true;root.querySelectorAll('button').forEach(b=>b.disabled=true);try{if(action==='logout'){const old=session;if(vault())await originalLogout();workspace='home';personalFilters={date:'',state:'active'};epoch++;session=null;company=null;admin=false;workers=[];services=[];blocks=[];events=[];members=[];lastAt='';createOpen=false;createDraft={};createError='';section='agenda';dirtyForm=false;filters={date:day(),state:'active',worker:''};login();if(old)await raw('/auth/v1/logout',{},old.access_token).catch(()=>{});return}if(action==='refresh'){if(createOpen){status('Guarda o cierra el formulario antes de actualizar.');return}await refresh();return}if(action==='import-blocks'){const message=await importBlocks();await refresh();status(message);return}if(action==='unblock'){const block=blocks.find(x=>x.id===b.dataset.id);await command('remove_availability',{id:block.id,employee_id:block.employee_id})}else{const s=services.find(s=>s.id===b.dataset.id);if(!s)throw new Error('Actualiza la lista de servicios.');const payload={id:s.id,version:s.version};if(action==='assign'){payload.employee_id=[...root.querySelectorAll('[data-worker]')].find(el=>el.dataset.worker===s.id).value;payload.mode=[...root.querySelectorAll('[data-mode]')].find(el=>el.dataset.mode===s.id).value;const conflict=legacyConflict(payload.employee_id,s);if(conflict)throw new Error(conflict);if(vault())await importBlocks()}if(action==='incident'||action==='reject'){const detail=prompt(action==='incident'?'Describe la incidencia:':'Motivo del rechazo (opcional):');if(detail===null)return;payload.detail=detail;if(action==='incident'&&!detail.trim())throw new Error('Describe la incidencia.')}if(['cancel','complete'].includes(action)&&!confirm(action==='cancel'?'¿Cancelar este servicio? Se conservará en el historial.':'¿Confirmas que has terminado este servicio?'))return;await command(action,payload)}await refresh();status('Cambio guardado.')}catch(err){status(err.message,true);if(/cambiado|versión/.test(err.message)){await refresh();status(err.message,true)}}finally{busy=false;root.querySelectorAll('button').forEach(b=>b.disabled=false)}});
function open(){dirtyForm=false;root.hidden=false;if(session){workspace=admin?(desktop()?'home':'personal'):'personal';render();refresh()}else login();root.querySelector('input,button')?.focus()}
window.umecOpenCoordination=()=>{dirtyForm=false;root.hidden=false;workspace=admin&&desktop()?'coordination':'personal';if(session){render();refresh()}else login()};
const originalAssignmentPanel=employeeAssignmentPanel;
employeeAssignmentPanel=function(s){if(!s.coord)return originalAssignmentPanel(s);return '<div class="notice">Coordinación: '+e(labels[s.coord.status]||s.coord.status)+'<p>El horario y la asignación se gestionan desde el Centro de Coordinación.</p><button class="btn" type="button" onclick="umecOpenCoordination()">Abrir coordinación</button></div>'};
const originalServiceCard=serviceCard;
serviceCard=function(s,pending){let html=originalServiceCard(s,pending);if(s.coord)html=html.replace('</div>','<span class="tag">Coordinación: '+e(labels[s.coord.status]||s.coord.status)+'</span></div>');return html};
const originalSaveServiceEdit=saveServiceEdit;
saveServiceEdit=async function(){if(editorService()?.coord){open();return}return originalSaveServiceEdit()};
const originalCancel=cancelService;
cancelService=async function(id){const s=vault()?.servicios.find(s=>s.id===id);if(!s?.coord)return originalCancel(id);if(!session||!admin||company!==s.coord.company){open();return}if(!confirm('¿Cancelar el servicio en coordinación y Gestión?'))return;try{const remote=services.find(s=>s.id===id);if(!remote)throw new Error('Actualiza coordinación primero.');await command('cancel',{id,version:remote.version});await refresh();}catch(err){alert(err.message)}};
const originalClose=closeService;
closeService=function(id){const s=vault()?.servicios.find(s=>s.id===id);if(s?.coord&&s.coord.status!=='completed'){alert('El trabajador debe finalizar el servicio en coordinación antes de cerrar sus cobros.');open();return}return originalClose(id)};
const originalLogout=logout;
logout=async function(){const old=session;createOpen=false;createDraft={};createError='';section='agenda';workspace='home';personalFilters={date:'',state:'active'};epoch++;session=null;company=null;admin=false;workers=[];services=[];blocks=[];events=[];members=[];await originalLogout();root.hidden=false;login();if(old)await raw('/auth/v1/logout',{},old.access_token).catch(()=>{})};
const entry=document.createElement('button');entry.type='button';entry.className='coord-entry coord-entry-desktop';entry.textContent='◈ Mi espacio UMEC';entry.addEventListener('click',open);document.querySelector('.nav')?.append(entry);
const team=document.createElement('button');team.type='button';team.className='btn light';team.style.cssText='width:100%;margin-top:14px';team.textContent='Volver a mi cuenta UMEC';team.addEventListener('click',open);document.querySelector('.auth-card')?.append(team);
setInterval(()=>{if(session&&!root.hidden&&!busy&&!dirtyForm&&!createOpen&&document.visibilityState==='visible'&&!root.querySelector('input:focus,select:focus,textarea:focus'))refresh()},15000);
window.addEventListener('online',()=>{if(session&&!root.hidden&&!dirtyForm&&!createOpen)refresh()});window.addEventListener('focus',()=>{if(session&&!root.hidden&&!busy&&!dirtyForm&&!createOpen)refresh()});document.addEventListener('visibilitychange',()=>{if(session&&!root.hidden&&document.visibilityState==='visible'&&!busy&&!dirtyForm&&!createOpen)refresh()});
let wasDesktop=desktop();window.addEventListener('resize',()=>{if(desktop()!==wasDesktop){wasDesktop=desktop();if(session&&!root.hidden)render()}});
root.addEventListener('input',event=>{if(event.target.closest('form'))dirtyForm=true});
root.addEventListener('change',event=>{if(event.target.closest('form')||event.target.matches('[data-worker],[data-mode]'))dirtyForm=true});
const legacyHome=document.createElement('button');legacyHome.type='button';legacyHome.className='btn light small';legacyHome.textContent='Mi espacio UMEC';legacyHome.addEventListener('click',open);document.querySelector('.top')?.append(legacyHome);open();
